use verus::prelude::*;

#[verifier::requires(true)]
#[verifier::ensures(
    result
    ==
    // can serve m special from each pile, and then n regular from the
    // remaining cookies total
    (a >= m && b >= m
     && (a as u16 + b as u16) >= (n as u16 + 2*m as u16))
)]
pub fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> bool {
    // Branch 1: if pile a is too small for the m special guests,
    // we must return false, and indeed the spec is false here
    if a < m {
        assert!(
            !(a >= m && b >= m
              && (a as u16 + b as u16) >= (n as u16 + 2*m as u16))
        );
        return false;
    }
    // Branch 2: similarly for pile b
    if b < m {
        assert!(
            !(a >= m && b >= m
              && (a as u16 + b as u16) >= (n as u16 + 2*m as u16))
        );
        return false;
    }

    // Now we know a >= m and b >= m
    let total_cookies = a as u16 + b as u16;
    let required_cookies = n as u16 + 2*m as u16;
    let res = total_cookies >= required_cookies;
    // Check that under the assumptions a>=m, b>=m the spec
    // exactly becomes `total_cookies >= required_cookies`
    assert!(
        res
        == (a >= m && b >= m && total_cookies >= required_cookies)
    );
    res
}

